def should_fire(rule, snap, now):
    if now - snap.taken_at > MAX_SNAPSHOT_AGE:
        return False  # stale: never evaluate old prices
    hit = (snap.price > rule.target if rule.direction == "ABOVE"
           else snap.price < rule.target)
    cooling = rule.last_fired_at and now - rule.last_fired_at < rule.cooldown
    return hit and not cooling

def visible_projects(user):
    if user.role == Role.ADMIN:
        return Project.objects.all()
    return Project.objects.filter(
        Q(members=user) | Q(department__managers=user)
    ).distinct()

@router.get("/projects/{project_id}/tasks", response=list[TaskOut])
def project_tasks(request, project_id: int):
    project = visible_projects(request.auth).filter(id=project_id).first()
    if project is None:
        raise HttpError(403, "Not a member of this project")
    return project.tasks.all()
